void need(bool v,const std::string &why){TORCH_CHECK(v,"[TRAIN scale diagnosis] ",why);}
std::string quote(const std::string &s){std::ostringstream o;o<<'"';for(unsigned char c:s){if(c=='"'||c=='\\')o<<'\\'<<c;else if(c=='\n')o<<"\\n";else if(c=='\r')o<<"\\r";else if(c=='\t')o<<"\\t";else if(c<32)o<<"\\u"<<std::hex<<std::setw(4)<<std::setfill('0')<<int(c)<<std::dec;else o<<c;}return o.str()+'"';}
std::string number(double v){if(!std::isfinite(v))return "null";std::ostringstream o;o<<std::setprecision(17)<<v;return o.str();}
std::string arr(const std::vector<std::string> &v){std::string o="[";for(size_t j=0;j<v.size();++j){if(j)o+=',';o+=v[j];}return o+']';}
std::string obj(const std::vector<std::pair<std::string,std::string>> &v){std::string o="{";for(size_t j=0;j<v.size();++j){if(j)o+=',';o+=quote(v[j].first)+':'+v[j].second;}return o+'}';}
