void verify_inputs(){for(const auto &p:inputs)need(fs::file_size(p.path)==p.bytes&&hash(p.path)==p.sha,"declared TRAIN input changed: "+std::string(p.path));}
std::string input_json(){std::vector<std::string> v;for(const auto &p:inputs)v.push_back(obj({{"path",quote(p.path)},{"sha256",quote(p.sha)},{"bytes",std::to_string(p.bytes)}}));return arr(v);}
void open(torch::serialize::InputArchive &a,size_t index){need(index<inputs.size()&&opened.insert(index).second,"actual loader allowlist/unique access");const auto &p=inputs[index];need(fs::file_size(p.path)==p.bytes&&hash(p.path)==p.sha,"loader hash pin");a.load_from(p.path,torch::kCPU);}
T read(torch::serialize::InputArchive &a,const char *name){T t;a.read(name,t,true);need(t.defined()&&t.device().is_cpu()&&!t.requires_grad(),std::string(name)+" detached CPU contract");return t;}
std::string text(torch::serialize::InputArchive &a,const char *name){const auto t=read(a,name).contiguous();need(t.dim()==1&&t.scalar_type()==torch::kUInt8,std::string(name)+" text type");return{reinterpret_cast<const char*>(t.const_data_ptr<uint8_t>()),size_t(t.numel())};}
void shape(const T &t,at::IntArrayRef s,torch::ScalarType type,const char *why){need(t.sizes()==s&&t.scalar_type()==type,std::string(why)+" shape/type");}
void finite(const T &t,const char *why){need(torch::isfinite(t).all().item<bool>(),std::string(why)+" finite");}
void equal(const T &a,const T &b,const char *why){need(torch::equal(a,b),why);++checks;}
void bound(double actual,double expected,const std::string &kind){need(std::isfinite(actual)&&std::isfinite(expected),"nonfinite "+kind);const auto e=std::abs(actual-expected)/(1.+std::abs(expected));errors[kind]=std::max(errors[kind],e);need(e<=tolerance,"numerical admission failed: "+kind);++checks;}
void bound(const T &a,const T &b,const std::string &kind){need(a.sizes()==b.sizes(),"comparison shape "+kind);const auto e=((a-b).abs()/(1.+b.abs())).max().item<double>();need(std::isfinite(e),"nonfinite "+kind);errors[kind]=std::max(errors[kind],e);need(e<=tolerance,"numerical admission failed: "+kind);++checks;}

