struct Targets{T values,valid,ids,groups;};
Targets load_targets(){torch::serialize::InputArchive a;open(a,2);Targets t{read(a,"targets"),read(a,"valid"),read(a,"row_ids"),read(a,"group_ids")};shape(t.values,{N,K},torch::kFloat64,"targets");shape(t.valid,{N,K},torch::kBool,"target support");shape(t.ids,{N},torch::kInt64,"target row ids");shape(t.groups,{N},torch::kInt64,"target groups");finite(t.values,"targets");need(t.valid.all().item<bool>()&&t.ids.slice(0,1).gt(t.ids.slice(0,0,N-1)).all().item<bool>(),"full chronological TRAIN targets");return t;}
struct Method{std::string model;int64_t width;Features feature;T fm,fs,tm,ts,w,b,saved,valid,prediction,prefix,suffix,intercept,prefix_shift,prediction_delta;};
