std::vector<double> values(const T &t,const Context &context){const auto x=t.contiguous();need(x.dim()==1&&x.size(0)==N,"row vector");const auto a=x.accessor<double,1>();std::vector<double> out;for(auto i=context.begin;i<context.end;++i)if(std::isfinite(a[i]))out.push_back(a[i]);return out;}
std::string stats(const T &t,const Context &context){auto v=values(t,context);const auto n=v.size();double mean=nan,lo=nan,hi=nan,sd=nan,rms=nan;if(n){mean=std::accumulate(v.begin(),v.end(),0.)/n;lo=*std::min_element(v.begin(),v.end());hi=*std::max_element(v.begin(),v.end());double squared=0,centered=0;for(const auto x:v){squared+=x*x;centered+=(x-mean)*(x-mean);}rms=std::sqrt(squared/n);sd=std::sqrt(centered/n);}return obj({{"count",std::to_string(n)},{"mean",number(mean)},{"median",number(median(v))},{"min",number(lo)},{"max",number(hi)},{"std",number(sd)},{"rms",number(rms)}});}
std::string association(const T &left,const T &right,const Context &context){const auto x=left.contiguous(),y=right.contiguous();const auto a=x.accessor<double,1>(),b=y.accessor<double,1>();std::vector<double> u,v,lu,lv;for(auto i=context.begin;i<context.end;++i)if(std::isfinite(a[i])&&std::isfinite(b[i])){u.push_back(a[i]);v.push_back(b[i]);if(a[i]>0&&b[i]>0){lu.push_back(std::log(a[i]));lv.push_back(std::log(b[i]));}}
  const auto corr=[](const std::vector<double> &a,const std::vector<double> &b){if(a.size()<2)return nan;const auto n=a.size();const double am=std::accumulate(a.begin(),a.end(),0.)/n,bm=std::accumulate(b.begin(),b.end(),0.)/n;double covariance=0,av=0,bv=0;for(size_t i=0;i<n;++i){const auto x=a[i]-am,y=b[i]-bm;covariance+=x*y;av+=x*x;bv+=y*y;}return av>0&&bv>0?std::clamp(covariance/std::sqrt(av*bv),-1.,1.):nan;};
  return "\"count\":"+std::to_string(u.size())+",\"pearson\":"+number(corr(u,v))+",\"positive_log_count\":"+std::to_string(lu.size())+",\"positive_log_pearson\":"+number(corr(lu,lv));}
std::string moment_summary(const T &tensor,const std::string &family,int64_t channel,int64_t feature,int64_t partition){std::vector<std::string> cs;const std::array<const char*,7> names{"count","mean","rms","sd","drift_share","bank_rms","floor_active"};
  for(const auto &context:contexts){std::vector<std::pair<std::string,std::string>> fields;for(int64_t j=0;j<std::min<int64_t>(tensor.size(-1),6);++j)fields.emplace_back(names[j],stats(tensor.select(1,channel).select(1,feature).select(1,partition).select(1,j),context));const auto active=tensor.size(-1)>6?tensor.select(1,channel).select(1,feature).select(1,partition).select(1,6).slice(0,context.begin,context.end).sum().item<double>():0;cs.push_back(obj({{"context",quote(context.name)},{"metrics",obj(fields)},{"floor_active_rows",number(active)}}));}
  return obj({{"family",quote(family)},{"channel",std::to_string(channel)},{"feature",std::to_string(family.starts_with("close_")?3:feature)},{"partition",std::to_string(partition)},{"contexts",arr(cs)}});
}
struct Coordinate{int64_t count=0;double mean=nan,sd=nan,rms=nan,squares=0,centered=0,mean_square=0,variance=0;};
struct Group{double squares=0,centered=0,mean_square=0,variance=0;};
std::string bank_balance(const Derived &d,const Context &context){std::vector<std::string> coords;std::map<std::string,Group> groups;const auto bank=d.bank.accessor<double,2>();const auto valid=d.bank_valid.accessor<bool,2>();
  for(int64_t j=0;j<C*F*10;++j){Coordinate x;std::vector<double> v;for(auto i=context.begin;i<context.end;++i)if(valid[i][j])v.push_back(bank[i][j]);x.count=v.size();if(x.count){x.mean=std::accumulate(v.begin(),v.end(),0.)/x.count;for(const auto a:v){x.squares+=a*a;x.centered+=(a-x.mean)*(a-x.mean);}x.mean_square=x.squares/x.count;x.variance=x.centered/x.count;x.rms=std::sqrt(x.mean_square);x.sd=std::sqrt(x.variance);}
    const auto channel=j/(F*10),feature=(j/10)%F,moment=j%10;std::vector<std::string> names{"total",moment<2?"global_slots":"quarter_slots","channel_"+std::to_string(channel),"feature_"+std::to_string(feature)};if(moment==0)names.push_back("global_mean");if(moment==1)names.push_back("global_rms");if(moment>=2)names.push_back("quarter_"+std::to_string((moment-2)/2));if(feature==3)names.push_back("close_slots");
    for(const auto &name:names){auto &g=groups[name];g.squares+=x.squares;g.centered+=x.centered;g.mean_square+=x.mean_square;g.variance+=x.variance;}
    coords.push_back(obj({{"coordinate",std::to_string(j)},{"channel",std::to_string(channel)},{"feature",std::to_string(feature)},{"moment",std::to_string(moment)},{"count",std::to_string(x.count)},{"mean",number(x.mean)},{"std",number(x.sd)},{"rms",number(x.rms)},{"sum_squares",number(x.squares)},{"centered_sum_squares",number(x.centered)},{"mean_square",number(x.count?x.mean_square:nan)},{"variance",number(x.count?x.variance:nan)}}));
  }
  std::vector<std::string> grouped;for(const auto &[name,g]:groups)grouped.push_back(obj({{"group",quote(name)},{"sum_squares",number(g.squares)},{"centered_sum_squares",number(g.centered)},{"mean_square_sum",number(g.mean_square)},{"variance_sum",number(g.variance)},{"raw_squared_share",number(groups["total"].squares>0?g.squares/groups["total"].squares:nan)},{"centered_variance_share",number(groups["total"].variance>0?g.variance/groups["total"].variance:nan)}}));
  return obj({{"context",quote(context.name)},{"coordinates",arr(coords)},{"groups",arr(grouped)}});
}
using Metrics=std::map<std::string,T>;
Metrics metrics(const Derived &d){Metrics out;const auto get=[&](int64_t c,const std::string &name,const T &v){out["c"+std::to_string(c)+'.'+name]=v.contiguous();};
  for(int64_t c=0;c<C;++c){get(c,"level_mean",d.levels.select(1,c).select(1,1));get(c,"level_median",d.levels.select(1,c).select(1,2));for(const auto &[name,j]:std::vector<std::pair<std::string,int64_t>>{{"mean",1},{"rms",2},{"sd",3},{"drift_share",4}}){get(c,"scaled_"+name,d.scaled.select(1,c).select(1,3).select(1,0).select(1,j));get(c,"raw_"+name,d.close.select(1,c).select(1,0).select(1,0).select(1,j));}
    for(const auto &[name,k]:std::vector<std::pair<std::string,int64_t>>{{"relative",1},{"log",2}})for(const auto &[suffix,j]:std::vector<std::pair<std::string,int64_t>>{{"rms",2},{"sd",3}})get(c,name+'_'+suffix,d.close.select(1,c).select(1,0).select(1,k).select(1,j));for(const auto &[suffix,j]:std::vector<std::pair<std::string,int64_t>>{{"rms",2},{"sd",3}})get(c,"symmetric_"+suffix,d.symmetric.select(1,c).select(1,3).select(1,0).select(1,j));}
  std::vector<std::string> names;for(const auto &[name,value]:out)if(name.starts_with("c0."))names.push_back(name.substr(3));for(const auto &name:names){const auto stack=torch::stack({out.at("c0."+name),out.at("c1."+name),out.at("c2."+name)},1);out["aggregate."+name]=torch::where(torch::isfinite(stack).all(1),stack.mean(1),torch::full({N},nan,torch::kFloat64));}return out;
}
std::string metric_associations(const Metrics &m){const std::vector<std::pair<std::string,std::string>> pairs{{"level_mean","scaled_rms"},{"level_mean","scaled_sd"},{"level_mean","raw_rms"},{"level_mean","raw_sd"},{"level_mean","relative_rms"},{"level_mean","relative_sd"},{"level_mean","log_rms"},{"level_mean","log_sd"},{"scaled_rms","scaled_sd"},{"scaled_rms","scaled_drift_share"},{"scaled_rms","log_sd"},{"scaled_rms","symmetric_sd"},{"scaled_sd","log_sd"},{"scaled_sd","symmetric_sd"},{"raw_rms","log_sd"},{"raw_rms","raw_sd"},{"relative_sd","log_sd"},{"symmetric_sd","log_sd"}};std::vector<std::string> out;for(const auto &context:contexts)for(const std::string prefix:{"c0.","c1.","c2.","aggregate."})for(const auto &[left,right]:pairs)out.push_back("{"+quote("context")+':'+quote(context.name)+','+quote("left")+':'+quote(prefix+left)+','+quote("right")+':'+quote(prefix+right)+','+association(m.at(prefix+left),m.at(prefix+right),context)+'}');return arr(out);}
std::string score(const T &prediction,const T &target,const Context &context){const auto p=prediction.slice(0,context.begin,context.end),y=target.slice(0,context.begin,context.end),e=p-y;const auto sse=e.square().sum().item<double>(),sst=(y-y.mean()).square().sum().item<double>();need(sst>0,"nonconstant target in fixed TRAIN context");return obj({{"total",std::to_string(context.end-context.begin)},{"valid",std::to_string(context.end-context.begin)},{"coverage","1"},{"r2",number(1.-sse/sst)},{"mae",number(e.abs().mean().item<double>())},{"rmse",number(std::sqrt(sse/(context.end-context.begin)))}});}
std::string method_report(const Method &m,const Targets &target,const T &parent_residual,const Metrics &metrics){std::vector<std::string> cs;for(const auto &context:contexts){std::vector<std::string> ts;for(int64_t task=0;task<K;++task){const std::map<std::string,T> components{{"prefix",m.prefix.select(1,task)},{"suffix",m.suffix.select(1,task)},{"prefix_shift",m.prefix_shift.select(1,task)},{"prediction_delta",m.prediction_delta.select(1,task)},{"parent_residual",parent_residual.select(1,task)},{"intercept",m.intercept[task].expand({N})}};std::vector<std::pair<std::string,std::string>> summaries;std::vector<std::string> associations;for(const auto &[name,vector]:components){summaries.emplace_back(name,stats(vector,context));if(name!="intercept")for(const auto &[metric,values]:metrics)if(metric.starts_with("aggregate."))associations.push_back("{"+quote("component")+':'+quote(name)+','+quote("metric")+':'+quote(metric)+','+association(vector,values,context)+'}');}ts.push_back(obj({{"task",quote(task_names[task])},{"linear",score(m.saved.select(1,task),target.values.select(1,task),context)},{"components",obj(summaries)},{"associations",arr(associations)}}));}cs.push_back(obj({{"context",quote(context.name)},{"tasks",arr(ts)}}));}return obj({{"model",quote(m.model)},{"width",std::to_string(m.width)},{"contexts",arr(cs)}});}
std::string method_witness(const Method &m){return obj({{"model",quote(m.model)},{"width",std::to_string(m.width)},{"raw_features",json(m.feature.values)},{"feature_valid",json(m.feature.valid)},{"feature_mean",json(m.fm)},{"feature_scale",json(m.fs)},{"ridge_weights",json(m.w)},{"ridge_intercept",json(m.b)},{"target_mean",json(m.tm)},{"target_scale",json(m.ts)},{"saved_ridge_predictions",json(m.saved)},{"prediction_valid",json(m.valid)},{"derived",obj({{"prediction",json(m.prediction)},{"prefix",json(m.prefix)},{"suffix",json(m.suffix)},{"intercept",json(m.intercept)},{"prefix_shift",json(m.prefix_shift)},{"prediction_delta",json(m.prediction_delta)}})}});}
void write_new(const fs::path &p,const std::string &text){const auto fd=::open(p.c_str(),O_CREAT|O_EXCL|O_WRONLY,0600);need(fd>=0,"exclusive write "+p.string());size_t offset=0;while(offset<text.size()){const auto n=::write(fd,text.data()+offset,text.size()-offset);if(n<=0){::close(fd);need(false,"write output");}offset+=n;}need(::fsync(fd)==0,"sync output");need(::close(fd)==0,"close output");}
